<include file="Public:header"/>	<div class="mainbox">	<!-- 	<div id="nav" class="mainnav_title">			<ul>				<a href="{pigcms{:U('Merchant_bill/index')}" class="on">商家对账</a>			</ul>		</div> -->		<table class="search_table" width="100%">			<tr>				<td style="width:60%;">					<form action="{pigcms{:U('Merchant/index')}" method="get">						<input type="hidden" name="c" value="Merchant_bill"/>						<input type="hidden" name="a" value="index"/>						筛选: 						<input type="text" class="input-text" name="search_month" style="width:120px;" id="d4311"  value="{pigcms{$_GET.search_month}" onfocus="WdatePicker({readOnly:true,dateFmt:'yyyy-MM', maxDate:'#F{\'%y-%M\'}'})"/>			   						<input type="text" name="keyword" class="input-text" placeholder="请输入商户名称" value="{pigcms{$_GET['keyword']}"/>											<input type="submit" value="查询" class="button"/>											</form>				</td>			</tr>		</table>					<div class="table-list">				<table width="100%" cellspacing="0">					<colgroup><col> <col> <col><col><col width="240" align="center"> </colgroup>					<thead>						<tr>							<th>商家名称</th>							<th>总销售额</th>							<th>总退款</th>							<th>总提现</th>							<th>总抽成</th>							<th>总佣金</th>							<th>平台余额</th>							<!-- <th class="textcenter">操作</th> -->						</tr>					</thead>					<tbody>						<if condition="is_array($merchant_list)">							<volist name="merchant_list" id="vo">								<tr>									<td>{pigcms{$vo.name}</td>									<td><a href="{pigcms{:U('order_list', $_GET)}&mer_id={pigcms{$vo.mer_id}">{pigcms{$vo.total_price}</a></td>									<td> <a href="{pigcms{:U('refund_order_list', $_GET)}&mer_id={pigcms{$vo.mer_id}">{pigcms{$vo.refund_money}</a></td>									<td><a href="{pigcms{:U('merchant_money_list', $_GET)}&mer_id={pigcms{$vo.mer_id}&type=withdraw">{pigcms{$vo.withdraw_money}</a></td>									<td><a href="{pigcms{:U('merchant_money_list', $_GET)}&mer_id={pigcms{$vo.mer_id}&type=system_take">{pigcms{$vo.system_take}</a></td>									<td><a href="{pigcms{:U('merchant_spread_list', $_GET)}&mer_id={pigcms{$vo.mer_id}">{pigcms{$vo.spread_money}</a></td>									<td><a href="{pigcms{:U('merchant_money_list', $_GET)}&mer_id={pigcms{$vo.mer_id}">{pigcms{$vo.income_money}</a></td>                                   																		<!-- <td class="textcenter"><a href="{pigcms{:U('order_list',array('mer_id'=>$vo['mer_id'],'search_month'=>$_GET['search_month']))}" style="    color: #1890FF; border: 1px solid #1890FF; padding: 4px 6px 4px 6px; border-radius: 4px;">对账</a></td> -->																	</tr>							</volist>							<tr><td class="textcenter pagebar" colspan="13">{pigcms{$pagebar}</td></tr>						<else/>							<tr><td class="textcenter red" colspan="13">列表为空！</td></tr>						</if>					</tbody>				</table>			</div>		</div><include file="Public:footer"/>